"use client"

import * as React from "react"
import { Check, Folder } from "lucide-react"
import { cn } from "@/lib/utils"
import { Avatar, AvatarFallback, AvatarImage, type AvatarColor } from "@/components/ui/avatar"
import { Badge, type BadgeColor } from "@/components/ui/badge"

/* ------------------------------------------------------------------ */
/* Timeline Event — activity entry with avatar/status rail             */
/* Figma: Timeline Event (722:58517)                                   */
/* ------------------------------------------------------------------ */

type TimelineEventProps = {
  /** Actor avatar (Type=event). */
  avatar?: { src?: string; initials?: string; color?: AvatarColor }
  /** Status dot (Type=step): tone + icon. */
  status?: { tone?: "success" | "primary" | "warning" | "muted"; icon?: React.ReactNode }
  title: React.ReactNode
  time?: React.ReactNode
  /** Small object chip under the title (Type=event) — e.g. project name. */
  object?: { icon?: React.ReactNode; label: React.ReactNode }
  /** Trailing badge/label on the title row (Type=step). */
  badge?: React.ReactNode
  badgeColor?: BadgeColor
  meta?: React.ReactNode
  /** Extra content below the title (comment excerpt, reactions, attachments …). */
  children?: React.ReactNode
  /** Draw the connector line to the next entry. */
  last?: boolean
  className?: string
}

const STATUS_TONE = {
  success: "bg-success text-success-foreground",
  primary: "bg-primary text-primary-foreground",
  warning: "bg-brand-quaternary text-foreground",
  muted: "bg-muted text-text-secondary",
}

function TimelineEvent({ avatar, status, title, time, object, badge, badgeColor = "grey", meta, children, last, className }: TimelineEventProps) {
  const lineColor = status?.tone === "success" ? "bg-success" : "bg-border"
  return (
    <div data-slot="timeline-event" className={cn("flex gap-4", className)}>
      <div className="flex w-9 shrink-0 flex-col items-center">
        {avatar ? (
          <Avatar size="lg" color={avatar.src ? undefined : avatar.color}>
            {avatar.src && <AvatarImage src={avatar.src} alt="" />}
            <AvatarFallback>{avatar.initials}</AvatarFallback>
          </Avatar>
        ) : (
          <span className={cn("grid size-8 place-items-center rounded-full [&_svg]:size-3.5", STATUS_TONE[status?.tone ?? "muted"])}>
            {status?.icon ?? <Check strokeWidth={1.5} />}
          </span>
        )}
        {!last && <span className={cn("mt-1 w-0.5 flex-1", lineColor)} />}
      </div>
      <div className={cn("flex min-w-0 flex-1 flex-col gap-1", !last && "pb-6")}>
        <div className="flex items-start justify-between gap-2">
          <p className="text-sm text-text-secondary [&_strong]:font-medium [&_strong]:text-foreground">{title}</p>
          {time && <span className="shrink-0 text-xs text-text-tertiary">{time}</span>}
          {badge && (
            <Badge color={badgeColor} badgeStyle="light" shape="pill" className="shrink-0">
              {badge}
            </Badge>
          )}
        </div>
        {object && (
          <span className="inline-flex w-fit items-center gap-1 rounded-md bg-muted px-2 py-0.5 text-[11px] text-text-secondary [&_svg]:size-3">
            {object.icon ?? <Folder strokeWidth={1.5} />}
            {object.label}
          </span>
        )}
        {meta && <p className="text-xs text-text-tertiary">{meta}</p>}
        {children}
      </div>
    </div>
  )
}

export { TimelineEvent }
export type { TimelineEventProps }

import * as React from "react"
import { mergeProps } from "@base-ui/react/merge-props"
import { useRender } from "@base-ui/react/use-render"
import { cva, type VariantProps } from "class-variance-authority"
import {
  Check,
  Loader2,
  Lock,
  Minus,
  Moon,
  TriangleAlert,
  X,
  type LucideIcon,
} from "lucide-react"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

// Hex per color - the same hue set as the Figma "Badge" component (600 step
// of each Primitives scale). Kept as plain hex (not CSS vars) so color-mix()
// below can compute the light/opacity variants at runtime.
const BADGE_COLORS = {
  blue: "#12AFF0",
  green: "#1AD598",
  red: "#F47690",
  yellow: "#FACA4A",
  purple: "#A584F3",
  indigo: "#555CF3",
  pink: "#FE6BBA",
  orange: "#F3654A",
  alternative: "#6E6D86",
  grey: "#A2A3A3",
  black: "#000000",
  white: "#FFFFFF",
} as const

type BadgeColor = keyof typeof BADGE_COLORS

const badgeVariants = cva(
  cn(
    "group/badge inline-flex w-fit shrink-0 items-center justify-center overflow-hidden border border-transparent font-semibold whitespace-nowrap transition duration-fast ease-entrance [&>svg]:pointer-events-none",
    // Rendered as a button or link, a badge is a chip: it answers the pointer
    // and the keyboard like any other control.
    //
    // The hover cue is a ring in the label's own colour, not a brightness
    // filter. brightness() moves fill and label together, and because the label
    // polarity differs per colour — a deep hue on a bright fill in light mode,
    // white on indigo and alternative in dark mode — no single factor is safe in
    // both directions: brightness-95/125 measured 3.40:1 on dark alternative,
    // 3.81:1 on dark indigo and 4.44:1 on light orange, and the factors that
    // clear AA everywhere (98%/106%) are too small to see. A ring changes
    // nothing about the label's backdrop, so contrast is unaffected whatever the
    // colour. See /scripts/contrast-audit.mjs, which reads this hover treatment
    // out of this file.
    "[&:is(button,a)]:cursor-pointer [&:is(button,a)]:outline-none [&:is(button,a)]:hover:ring-2 [&:is(button,a)]:hover:ring-current/30 [&:is(button,a)]:active:scale-95 motion-reduce:[&:is(button,a)]:active:scale-100 [&:is(button,a)]:focus-ring"
  ),
  {
    variants: {
      shape: {
        rounded: "rounded-md",
        pill: "rounded-full",
      },
      size: {
        sm: "h-5 gap-1 px-2 text-xs [&>svg]:size-3!",
        md: "h-6 gap-1.5 px-2.5 text-sm [&>svg]:size-3.5!",
      },
    },
    defaultVariants: {
      shape: "rounded",
      size: "sm",
    },
  }
)

type BadgeStyle = "plain" | "light" | "light_border" | "border_color" | "border_grey" | "ghost"

// Hues that have a Figma tint pair (`tint/<hue>` surface + `tint-text/<hue>`
// text, both mode-aware). Grey, black and white have none and fall back to
// color-mix() below.
const TINTED: readonly BadgeColor[] = ["blue", "green", "red", "yellow", "purple", "indigo", "pink", "orange", "alternative"]

// Text on a solid fill — the Figma Badge "primary" state: white on indigo,
// alternative and black (≥ 5:1), and on every lighter hue the darkest step of that
// same hue (the Primitives <hue>-1000 variable, the same one Figma binds), so label
// and icon still read as one tone and pass AA (6.1–8.0:1). The pale tint used before
// fell to 1.5–3:1. Mode-independent on purpose: the fill keeps its bright hue in dark mode.
const WHITE_TEXT_ON: readonly BadgeColor[] = ["indigo", "alternative", "black"]

const SOLID_TEXT: Partial<Record<BadgeColor, string>> = {
  blue: "var(--blue-1000)",
  purple: "var(--purple-1000)",
  pink: "var(--pink-1000)",
  red: "var(--red-1000)",
  orange: "var(--orange-1000)",
  yellow: "var(--yellow-1000)",
  green: "var(--green-1000)",
  grey: "#2D2E2E",
}

// The two achromatic badges are spelled out in Figma rather than derived: a
// black badge pales to the grey scale, a white one to the surface grey — a
// color-mix of #000 or #FFF lands somewhere else entirely.
// `text` sits on the badge's own fill; `ink` sits on the card or on nothing at
// all (outline, ghost), so it has to follow the mode — pure black there would
// vanish into a dark card.
const ACHROMATIC: Partial<Record<BadgeColor, { bg: string; text: string; ink: string; border: string }>> = {
  black: { bg: "var(--dark-200)", text: "#000000", ink: "var(--foreground)", border: "var(--dark-300)" },
  white: { bg: "var(--muted)", text: "var(--foreground)", ink: "var(--foreground)", border: "var(--border-control)" },
  // Grey has no tint pair; its 600 hue (#A2A3A3) is a fill colour, too pale
  // for a label on white. Text takes the tertiary text token instead (AA in
  // both modes), the surface keeps the grey hue.
  grey: {
    // 10 % (not 16 %) keeps the tertiary text at 4.7:1 on the surface — 16 % measured 4.46:1
    bg: "color-mix(in srgb, #A2A3A3 10%, var(--card))",
    text: "var(--text-tertiary)",
    ink: "var(--text-tertiary)",
    border: "var(--border-control)",
  },
}

// Figma Badge / Plain: the label sits on the page, not on a tint, so it takes the semantic text token
// (link, success, error) where one exists and the hue's tint-text everywhere else.
const GHOST_TEXT: Partial<Record<BadgeColor, string>> = {
  indigo: "var(--text-link)",
  green: "var(--text-success)",
  red: "var(--text-error)",
}

function styleToCss(color: BadgeColor, style: BadgeStyle) {
  const hex = BADGE_COLORS[color]
  const tinted = TINTED.includes(color)
  const flat = ACHROMATIC[color]
  const tintBg = flat ? flat.bg : tinted ? `var(--tint-${color})` : `color-mix(in srgb, ${hex} 12%, var(--card))`
  const tintText = flat ? flat.text : tinted ? `var(--tint-text-${color})` : hex === "#FFFFFF" ? "#000000" : hex
  const inkText = flat ? flat.ink : tintText
  const tintBorder = flat
    ? flat.border
    : tinted
      ? `color-mix(in srgb, var(--tint-text-${color}) 40%, var(--card))`
      : `color-mix(in srgb, ${hex} 40%, var(--card))`
  // Figma Badge / Outline: the rim is the tint-text token of the hue itself (a variable, not a blend).
  const outlineBorder = flat ? flat.border : tinted ? `var(--tint-text-${color})` : tintBorder
  switch (style) {
    case "plain":
      return {
        background: hex,
        borderColor: hex,
        color: WHITE_TEXT_ON.includes(color) ? "#FFFFFF" : (SOLID_TEXT[color] ?? "#000000"),
      }
    case "light":
      return {
        background: tintBg,
        borderColor: "transparent",
        color: tintText,
      }
    case "light_border":
      return {
        background: tintBg,
        borderColor: outlineBorder,
        color: tintText,
      }
    case "border_color":
      return {
        background: "var(--card)",
        borderColor: tintBorder,
        color: inkText,
      }
    case "border_grey":
      return {
        background: "var(--card)",
        borderColor: "var(--border)",
        color: inkText,
      }
    case "ghost":
      return {
        background: "transparent",
        borderColor: "transparent",
        color: GHOST_TEXT[color] ?? inkText,
      }
  }
}

function Badge({
  className,
  shape,
  size = "sm",
  color = "blue",
  badgeStyle = "plain",
  style,
  render,
  dot,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: useRender.ComponentProps<"span"> &
  VariantProps<typeof badgeVariants> & {
    color?: BadgeColor
    badgeStyle?: BadgeStyle
    dot?: boolean
    onRemove?: () => void
    removeLabel?: string
  }) {
  // Don't render the remove button when the badge is a button/link (`render`),
  // as that would nest interactive elements.
  const removeButton = onRemove && render === undefined ? (
    <button
      type="button"
      data-slot="badge-remove"
      aria-label={removeLabel}
      onClick={onRemove}
      className="-mr-1 ml-0.5 inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full outline-none transition duration-fast ease-entrance hover:bg-current/15 active:scale-90 motion-reduce:active:scale-100 focus-ring"
    >
      <X aria-hidden="true" className="size-3" />
    </button>
  ) : null

  return useRender({
    defaultTagName: "span",
    props: mergeProps<"span">(
      {
        className: cn(badgeVariants({ shape, size }), className),
        style: { ...styleToCss(color, badgeStyle), ...style },
        children: (
          <>
            {dot && (
              <span
                data-slot="badge-dot"
                aria-hidden="true"
                className="size-1.5 shrink-0 rounded-full bg-current"
              />
            )}
            {opticalCenter(children)}
            {removeButton}
          </>
        ),
      },
      props
    ),
    render,
    state: {
      slot: "badge",
      color,
      badgeStyle,
      size,
      ...(dot ? { dot: true } : {}),
    },
  })
}

type BadgeCounterTone = "neutral" | "brand" | "danger"

const BADGE_COUNTER_TONE_CLASSES: Record<BadgeCounterTone, string> = {
  neutral: "bg-bg-subtle text-foreground data-[zero]:text-text-tertiary",
  brand: "bg-primary text-primary-foreground",
  danger: "bg-destructive text-destructive-foreground",
}

const BADGE_COUNTER_KIND_CLASSES: Record<"inline" | "overlay", string> = {
  inline: "h-5 min-w-5 px-1.5 text-xs font-semibold",
  overlay: "absolute top-0 right-0 z-10 h-4 min-w-4 translate-x-1/2 -translate-y-1/2 px-1 text-[11px] font-medium ring-2 ring-card",
}

function BadgeCounter({
  count,
  max = 99,
  tone = "neutral",
  overlay = false,
  hideZero,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  count: number
  max?: number
  tone?: BadgeCounterTone
  overlay?: boolean
  hideZero?: boolean
}) {
  const resolvedHideZero = hideZero ?? overlay
  const shown = Math.max(0, Math.trunc(count))
  if (shown <= 0 && resolvedHideZero) return null
  const text = shown > max ? `${max}+` : String(shown)

  return (
    <span
      data-slot="badge-counter"
      data-tone={tone}
      data-kind={overlay ? "overlay" : "inline"}
      data-zero={shown === 0 ? "" : undefined}
      className={cn(
        "inline-flex items-center justify-center rounded-full tabular-nums leading-none whitespace-nowrap select-none",
        BADGE_COUNTER_KIND_CLASSES[overlay ? "overlay" : "inline"],
        BADGE_COUNTER_TONE_CLASSES[tone],
        className
      )}
      {...props}
    >
      <span className="optical-center">{text}</span>
    </span>
  )
}

type BadgeIndicatorKind = "unread" | "online" | "away" | "busy" | "offline" | "check" | "warning" | "lock"

const DEFAULT_LABELS: Record<BadgeIndicatorKind, string> = {
  unread: "Unread",
  online: "Online",
  away: "Away",
  busy: "Busy",
  offline: "Offline",
  check: "Done",
  warning: "Warning",
  lock: "Locked",
}

const INDICATOR_CONFIG: Record<
  BadgeIndicatorKind,
  {
    root: string
    size: Record<"sm" | "md", string>
    icon?: LucideIcon
    iconSize: Record<"sm" | "md", string>
    strokeWidth?: number
    fill?: boolean
  }
> = {
  unread: {
    root: "bg-primary",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  online: {
    root: "bg-success",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  offline: {
    root: "border-[1.5px] border-text-tertiary bg-transparent",
    size: { sm: "size-2", md: "size-2.5" },
    iconSize: { sm: "", md: "" },
  },
  busy: {
    root: "bg-destructive text-destructive-foreground",
    size: { sm: "size-2", md: "size-2.5" },
    icon: Minus,
    iconSize: { sm: "size-1.5", md: "size-2" },
    strokeWidth: 4,
  },
  away: {
    root: "bg-transparent text-brand-quaternary",
    size: { sm: "size-2", md: "size-2.5" },
    icon: Moon,
    iconSize: { sm: "size-2", md: "size-2.5" },
    strokeWidth: 0,
    fill: true,
  },
  check: {
    root: "bg-success text-success-foreground",
    size: { sm: "size-4", md: "size-5" },
    icon: Check,
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
  warning: {
    root: "bg-brand-quaternary text-brand-quaternary-foreground",
    size: { sm: "size-4", md: "size-5" },
    icon: TriangleAlert,
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
  lock: {
    root: "bg-foreground text-background",
    size: { sm: "size-4", md: "size-5" },
    icon: Lock,
    iconSize: { sm: "size-2.5", md: "size-3" },
    strokeWidth: 2.5,
  },
}

function BadgeIndicator({
  kind,
  size = "sm",
  label,
  overlay = false,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  kind: BadgeIndicatorKind
  size?: "sm" | "md"
  label?: string
  overlay?: boolean
}) {
  const config = INDICATOR_CONFIG[kind]
  const IconComponent = config.icon

  // Overlay mode requires a relative parent to anchor against.
  return (
    <span
      role="img"
      aria-label={label ?? DEFAULT_LABELS[kind]}
      data-slot="badge-indicator"
      data-kind={kind}
      data-size={size}
      data-overlay={overlay ? "" : undefined}
      className={cn(
        "inline-flex shrink-0 items-center justify-center rounded-full",
        overlay && "absolute top-0 right-0 z-10 translate-x-1/2 -translate-y-1/2 ring-2 ring-card",
        config.size[size],
        config.root,
        className
      )}
      {...props}
    >
      {IconComponent && (
        <IconComponent
          aria-hidden="true"
          className={cn(config.iconSize[size], config.fill && "fill-current")}
          strokeWidth={config.strokeWidth}
        />
      )}
    </span>
  )
}

type BadgeProcessingState = "pending" | "success" | "error"

function BadgeProcessing({
  state,
  children,
  ...props
}: Omit<React.ComponentProps<typeof Badge>, "color" | "badgeStyle" | "shape" | "dot" | "onRemove"> & {
  state: BadgeProcessingState
}) {
  const pending = state === "pending"
  const done = state === "success"

  const icon = pending ? (
    <Loader2 aria-hidden="true" className="animate-spin motion-reduce:animate-none" />
  ) : done ? (
    <Check aria-hidden="true" />
  ) : (
    <TriangleAlert aria-hidden="true" />
  )

  const color = pending ? "blue" : done ? "green" : "red"

  return (
    <Badge
      shape="pill"
      badgeStyle="light"
      color={color}
      data-state={state}
      role="status"
      aria-busy={pending ? true : undefined}
      {...props}
    >
      {icon}
      {children}
    </Badge>
  )
}

export { Badge, BadgeCounter, BadgeIndicator, BadgeProcessing, badgeVariants, BADGE_COLORS }
export type { BadgeColor, BadgeStyle, BadgeCounterTone, BadgeIndicatorKind, BadgeProcessingState }

import * as React from "react"

const isText = (node: React.ReactNode): node is string | number => typeof node === "string" || typeof node === "number"

/**
 * Puts the text of a circle, pill or badge on the cap-height centre (owner rule, 10 Nov 2026).
 *
 * A flex container centres the line box, and a line box is taller below the baseline than the cap height is
 * above it, so digits and capitals sit a little low. `optical-center` (line-height 1 and `text-box: trim-both
 * cap alphabetic`) shrinks the text to the cap height; it only works on a block of its own, so every run of
 * plain text inside the container is wrapped in a `<span className="optical-center">`. Elements (icons,
 * nested components) are left alone, and so is `null`, `false` and an empty string.
 *
 * Runs of text are merged into one span, so `+{n}` (two text children) stays one flex item.
 */
function opticalCenter(children: React.ReactNode): React.ReactNode {
  const nodes = React.Children.toArray(children)
  if (nodes.length === 0) return children
  const out: React.ReactNode[] = []
  let run: Array<string | number> = []
  const flush = () => {
    if (run.length === 0) return
    out.push(
      <span key={`optical-${out.length}`} className="optical-center">
        {run}
      </span>
    )
    run = []
  }
  for (const node of nodes) {
    if (isText(node)) run.push(node)
    else {
      flush()
      out.push(node)
    }
  }
  flush()
  return out
}

export { opticalCenter }

import type { CnFunction } from "cn"
import { createCn } from "cn/config"

/**
 * clsx + tailwind-merge, taught WunderUI's own theme utilities so they merge
 * in the right group: `text-label-sm` is a font size (not a text colour, which
 * dropped it next to `text-text-tertiary`), `bg-gradient-*` a background image
 * (not a colour that `bg-card` would remove), and the motion utilities
 * `ease-entrance …` and `duration-fast …` replace each other.
 */
export const cn: CnFunction = createCn({
  extend: {
    classGroups: {
      "font-size": [{ text: ["label-sm", "micro"] }],
      "bg-image": [
        {
          bg: [
            "gradient-primary",
            "gradient-indigo",
            "gradient-blue",
            "gradient-purple",
            "gradient-pink",
            "gradient-red",
            "gradient-orange",
            "gradient-yellow",
            "gradient-green",
            "gradient-alternative",
            "gradient-slate",
            "gradient-dark",
          ],
        },
      ],
      ease: [{ ease: ["entrance", "exit", "move", "overshoot", "spring"] }],
      duration: [{ duration: ["instant", "fast", "base", "slow", "deliberate", "ambient"] }],
    },
  },
})

"use client"

import * as React from "react"
import { Avatar as AvatarPrimitive } from "@base-ui/react/avatar"
import { Check, Moon } from "lucide-react"
import { cn } from "@/lib/utils"
import { opticalCenter } from "@/lib/optical-center"

/** Tinted initials — mirrors the Figma Avatar "Style=<hue>_primary" variants
 *  (tint/<hue> background + tint-text/<hue> text, both mode-aware tokens). */
type AvatarColor =
  | "indigo"
  | "blue"
  | "purple"
  | "pink"
  | "red"
  | "orange"
  | "yellow"
  | "green"
  | "alternative"
  | "grey"

type AvatarBadgeStatus = "available" | "busy" | "away" | "dnd" | "offline" | "unknown"

const AVATAR_COLOR_CLASSES: Record<AvatarColor, string> = {
  indigo: "bg-tint-indigo text-tint-text-indigo",
  blue: "bg-tint-blue text-tint-text-blue",
  purple: "bg-tint-purple text-tint-text-purple",
  pink: "bg-tint-pink text-tint-text-pink",
  red: "bg-tint-red text-tint-text-red",
  orange: "bg-tint-orange text-tint-text-orange",
  yellow: "bg-tint-yellow text-tint-text-yellow",
  green: "bg-tint-green text-tint-text-green",
  alternative: "bg-tint-alternative text-tint-text-alternative",
  grey: "bg-muted text-text-secondary",
}

// Owner rule (Oct 31 2026): the indicator sits top right with its centre on
// the corner of the shape. Circle of size s: centre at (0.854 s, 0.146 s).
// Rounded square of radius r: centre at (s - 0.293 r, 0.293 r). --badge-d is the dot size.
const BADGE_POSITION = "absolute top-[calc(14.645%-var(--badge-d)/2)] right-[calc(14.645%-var(--badge-d)/2)] z-10 inline-flex size-(--badge-d) items-center justify-center rounded-full bg-primary text-primary-foreground bg-blend-color ring-[1.5px] ring-(--surface) select-none [--badge-d:--spacing(2)] group-data-[shape=square]/avatar:top-[calc(var(--radius-md)*0.293-var(--badge-d)/2)] group-data-[shape=square]/avatar:right-[calc(var(--radius-md)*0.293-var(--badge-d)/2)]"

const STATUS_SHAPES: Record<AvatarBadgeStatus, React.ReactNode> = {
  available: <span aria-hidden className="size-full rounded-full bg-success" />,
  busy: (
    <span aria-hidden className="h-[20%] w-[60%] rounded-full bg-primary-foreground" />
  ),
  dnd: (
    <span aria-hidden className="h-[15%] w-[50%] rounded-full bg-error" />
  ),
  away: (
    <span aria-hidden className="flex size-[80%] items-center justify-center">
      <Moon className="size-full fill-current" strokeWidth={0} />
    </span>
  ),
  offline: null,
  unknown: null,
}

const STATUS_LABELS: Record<AvatarBadgeStatus, string> = {
  available: "Available",
  busy: "Busy",
  away: "Away",
  dnd: "Do not disturb",
  offline: "Offline",
  unknown: "Status unknown",
}

function Avatar({
  className,
  size = "default",
  shape = "circle",
  variant = "plain",
  color,
  interactive,
  selected,
  disabled,
  render,
  children,
  ...props
}: AvatarPrimitive.Root.Props & {
  /** Figma Avatar sizes: sm = 24px (2xs), xs = 28px, default = 36px (small), lg = 40px (medium), xl = 44px (large) */
  size?: "sm" | "xs" | "default" | "lg" | "xl"
  shape?: "circle" | "square"
  variant?: "plain" | "primary"
  /** Soft tint for initials avatars; ignored when an image renders. */
  color?: AvatarColor
  interactive?: boolean
  selected?: boolean
  disabled?: boolean
}) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      data-size={size}
      data-shape={shape}
      data-variant={variant}
      data-color={color}
      data-interactive={interactive ? "" : undefined}
      data-selected={selected ? "" : undefined}
      data-disabled={disabled ? "" : undefined}
      {...(interactive && disabled ? { disabled: true } : {})}
      aria-pressed={interactive ? selected : undefined}
      render={interactive ? render ?? <button type="button" /> : render}
      className={cn(
        "group/avatar relative flex size-9 shrink-0 select-none after:absolute after:inset-0 after:border after:border-border-control after:mix-blend-darken dark:after:mix-blend-lighten",
        "data-[shape=circle]:rounded-full data-[shape=circle]:after:rounded-full",
        "data-[shape=square]:rounded-md data-[shape=square]:after:rounded-md",
        "data-[size=sm]:size-6 data-[size=xs]:size-7 data-[size=lg]:size-10 data-[size=xl]:size-11",
        // Figma keeps the glyph at 16 px and only shrinks it on the two small sizes.
        "[&_svg]:size-4 data-[size=sm]:[&_svg]:size-3 data-[size=xs]:[&_svg]:size-3.5",
        "data-[variant=primary]:bg-primary data-[variant=primary]:text-primary-foreground data-[variant=primary]:after:border-transparent",
        color && AVATAR_COLOR_CLASSES[color],
        color && "after:border-transparent",
        interactive && "cursor-pointer focus-ring data-[interactive]:focus-visible:after:border-primary data-[interactive]:focus-visible:after:mix-blend-normal data-[interactive]:hover:ring-3 data-[interactive]:hover:ring-bg-page data-[interactive]:active:ring-3 data-[interactive]:active:ring-bg-subtle data-[interactive]:data-[disabled]:opacity-40 data-[interactive]:data-[disabled]:pointer-events-none data-[interactive]:data-[selected]:ring-3 data-[interactive]:data-[selected]:ring-bg-subtle",
        className
      )}
      {...props}
    >
      {children}
      {selected && (
        <span
          data-slot="avatar-check"
          aria-hidden
          className={cn(
            BADGE_POSITION,
            "[--badge-d:--spacing(4)]",
            "group-data-[size=sm]/avatar:[--badge-d:--spacing(3)] group-data-[size=sm]/avatar:[&>svg]:size-2",
            "group-data-[size=xs]/avatar:[--badge-d:--spacing(3.5)] group-data-[size=xs]/avatar:[&>svg]:size-2.5",
            "group-data-[size=default]/avatar:[&>svg]:size-3",
            "group-data-[size=lg]/avatar:[&>svg]:size-3",
            "group-data-[size=xl]/avatar:[&>svg]:size-3"
          )}
        >
          <Check className="size-3" strokeWidth={3} />
        </span>
      )}
    </AvatarPrimitive.Root>
  )
}

